import React from 'react';
import { Routes, Route } from 'react-router-dom';

// Placeholder component for the Blood Bank's main view
const IncomingRequests = () => <h2>Incoming Blood Requests</h2>;
const InventoryManagement = () => <h2>Inventory Management</h2>;

const BloodBankView = () => {
  return (
    <Routes>
      <Route path="/" element={<IncomingRequests />} />
      <Route path="/inventory" element={<InventoryManagement />} />
    </Routes>
  );
};

export default BloodBankView;
